const assetModuleURL=import.meta.url;
import{SELECTION_SHA}from'./pins.mjs';
const sha=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(x=>x.toString(16).padStart(2,'0')).join('');
export async function loadSelectedDoorApproach({fetcher=fetch,contract}){const read=async(name,pin)=>{const r=await fetcher(new URL(name,assetModuleURL));if(!r.ok)throw Error('DOOR_APPROACH_INPUT_MISSING');const b=await r.arrayBuffer();if(await sha(b)!==pin)throw Error('DOOR_APPROACH_PIN_MISMATCH');return b};const selection=JSON.parse(new TextDecoder().decode(await read('ROOT_SELECTION.json',SELECTION_SHA)));const proposal=JSON.parse(new TextDecoder().decode(await read('PROPOSAL.json',selection.proposalSHA)));await read('approach.source.txt',selection.moduleSHA);await read('STAIRS_PROPOSAL.json',selection.stairsProposalSHA);for(const row of proposal.rows){if(row.sourceImageSHA!==contract.sources[row.scene==='exterior'?'exterior:OPEN':row.scene].sha256)throw Error('DOOR_APPROACH_SOURCE_DRIFT');const foot=row.scene==='exterior'?contract.exteriorDoor.readFoot:contract.interiorDoor.returnFoot;if(JSON.stringify(foot)!==JSON.stringify(row.originalReadFootUnchanged))throw Error('DOOR_READFOOT_DRIFT')}return Object.freeze(selection)}
